<template><div class="knowledge-graph"><div class="graph-toolbar"><label class="graph-search"><Search :size="17"/><input v-model="search" aria-label="搜索知识节点" placeholder="搜索节点名称…"/></label><select v-model="filter" class="m-input" aria-label="筛选节点状态"><option value="all">全部状态</option><option value="learning">学习中</option><option value="review">有错题待回忆</option><option value="evidence">已有练习证据</option><option value="unstarted">尚无学习证据</option></select></div><div class="graph-controls"><button class="icon-button" aria-label="缩小知识图谱" @click="zoom=Math.max(.5,zoom-.15)"><Minus :size="17"/></button><span>{{ Math.round(zoom*100) }}%</span><button class="icon-button" aria-label="放大知识图谱" @click="zoom=Math.min(2.5,zoom+.15)"><Plus :size="17"/></button><button class="workspace-text-action" @click="zoom=1;pan={x:0,y:0}">重置视图</button></div><div v-if="!filtered.length" class="workspace-empty"><Waypoints :size="28"/><h3>这里还没有匹配的知识节点</h3><p>导入有双链的笔记或生成学习路径后，会出现实际关系。</p></div><div v-else class="graph-surface" @pointerdown="startPan" @pointermove="drag" @pointerup="stopPan" @pointercancel="stopPan"><svg viewBox="0 0 560 420" role="img" aria-label="可平移缩放的知识网络，节点可通过下方列表选择"><defs><pattern :id="gridId" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#91a6c5" opacity=".16"/></pattern></defs><rect width="560" height="420" :fill="`url(#${gridId})`"/><g :transform="`translate(${pan.x} ${pan.y}) scale(${zoom})`"><g v-for="(edge,index) in visibleEdges" :key="index"><line :x1="point(edge.from)?.x" :y1="point(edge.from)?.y" :x2="point(edge.to)?.x" :y2="point(edge.to)?.y" stroke="#8d7bff" stroke-opacity=".48" stroke-width="1.5"/><title>{{ edge.label }}</title></g><g v-for="node in positions" :key="node.id" class="knowledge-node" :class="`knowledge-node--${node.state}`" :transform="`translate(${node.x} ${node.y})`" role="button" tabindex="0" :aria-label="`${node.title}，${evidenceStates[node.state]}`" @pointerdown.stop @click="emit('select',node)" @keydown.enter.prevent="emit('select',node)" @keydown.space.prevent="emit('select',node)"><circle r="27" fill="var(--m-surface-2)" :stroke="node.id===selected?'#4dd8f0':node.state==='review'?'#ffc27b':node.kind==='note'?'#a99bff':'#4b6e9f'" :stroke-width="node.id===selected?2.5:1.5"/><circle v-if="node.state==='evidence'||node.state==='done'" r="6" fill="#60d8bd"/><text v-else text-anchor="middle" dominant-baseline="middle" fill="#c6d7ef" font-size="13">{{ node.kind==='note'?'文':node.kind==='task'?'行':'知' }}</text><text y="45" text-anchor="middle" fill="var(--m-text)" font-size="12">{{ node.title.length>11?node.title.slice(0,10)+'…':node.title }}</text></g></g></svg></div><div class="graph-legend"><span><i class="legend-note"/>原文 / 双链</span><span><i class="legend-evidence"/>有练习证据</span><span><i class="legend-review"/>错题待回忆</span></div><p class="workspace-caption">拖动空白区域平移，使用按钮缩放。每次显示最多 60 个匹配节点，可搜索缩小范围。紫色连线来自笔记链接或同阶段关系，不冒充已验证的前置依赖。</p><div class="graph-node-list" aria-label="可访问知识节点列表"><button v-for="node in filtered" :key="node.id" :aria-pressed="selected===node.id" @click="emit('select',node)"><span>{{ node.title }}</span><small>{{ evidenceStates[node.state] }}</small></button></div></div></template>
<script setup lang="ts">
import { computed,ref,useId } from 'vue'
import { Minus,Plus,Search,Waypoints } from 'lucide-vue-next'
import { evidenceStates,layoutGraph,type GraphEdge,type GraphNode } from '@/mobile/domain/knowledge-graph'
const props=defineProps<{nodes:GraphNode[];edges:GraphEdge[];selected?:string}>(),emit=defineEmits<{select:[node:GraphNode]}>(),search=ref(''),filter=ref('all'),zoom=ref(1),pan=ref({x:0,y:0}),gridId=useId()
const filtered=computed(()=>props.nodes.filter(n=>n.title.toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||n.state===filter.value)).slice(0,60)),positions=computed(()=>layoutGraph(filtered.value)),visibleEdges=computed(()=>props.edges.filter(e=>positions.value.some(n=>n.id===e.from)&&positions.value.some(n=>n.id===e.to)))
function point(id:string){return positions.value.find(n=>n.id===id)}
let last:{x:number;y:number}|null=null
function startPan(event:PointerEvent){last={x:event.clientX,y:event.clientY};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
function drag(event:PointerEvent){if(!last)return;const width=(event.currentTarget as HTMLElement).clientWidth;pan.value={x:pan.value.x+(event.clientX-last.x)*560/width,y:pan.value.y+(event.clientY-last.y)*560/width};last={x:event.clientX,y:event.clientY}}
function stopPan(){last=null}
</script>
<style scoped>.graph-toolbar{display:flex;gap:10px;flex-wrap:wrap}.graph-search{display:flex;align-items:center;gap:9px;flex:1;min-width:140px;border:1px solid var(--m-border-strong);border-radius:13px;padding:0 12px;background:var(--m-bg);color:var(--m-text-faint)}.graph-search input{min-width:0;width:100%;border:0;outline:0;color:var(--m-text);background:none;font:inherit;font-size:14px;height:46px}.graph-toolbar select{width:auto;max-width:100%;font-size:13px}.graph-controls{display:flex;align-items:center;gap:10px;margin:12px 0}.graph-controls>span{font-size:12px;min-width:42px;text-align:center;color:var(--m-text-faint)}.graph-controls .workspace-text-action{margin-left:auto;font-size:12px}.graph-surface{width:100%;border:1px solid var(--m-border);border-radius:18px;overflow:hidden;background:var(--m-bg);touch-action:none;cursor:grab}.graph-surface svg{width:100%;display:block}.knowledge-node{cursor:pointer;outline:none}.knowledge-node:focus circle:first-child{stroke:#fff;stroke-width:3}.graph-legend{display:flex;gap:15px;flex-wrap:wrap;margin:16px 0;font-size:11px;color:var(--m-text-faint)}.graph-legend span{display:flex;align-items:center;gap:6px}.graph-legend i{width:7px;height:7px;border-radius:50%;display:block}.legend-note{background:#a99bff}.legend-evidence{background:#60d8bd}.legend-review{background:#ffc27b}.graph-node-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:200px;overflow:auto}.graph-node-list button{display:grid;gap:6px;border:1px solid var(--m-border);border-radius:11px;padding:10px;text-align:left;font:inherit;color:var(--m-text-dim);background:var(--m-bg);min-height:54px;cursor:pointer}.graph-node-list button[aria-pressed=true]{border-color:var(--m-primary)}.graph-node-list span{font-size:13px}.graph-node-list small{font-size:11px;color:var(--m-text-faint)}</style>
